package storage

import (
	"bytes"
	"errors"
	"fmt"
	"path"
	"runtime"
	"sync"

	"github.com/syndtr/goleveldb/leveldb"
	"github.com/syndtr/goleveldb/leveldb/opt"
	"github.com/syndtr/goleveldb/leveldb/util"
	"github.com/zenon-network/go-zenon/common"
	"github.com/zenon-network/go-zenon/common/db"
	"github.com/zenon-network/go-zenon/common/types"
)

const (
	rollbackCacheSize = 100
)

var (
	storageByte  = []byte{85}
	rollbackByte = []byte{119}
)

func getConsensusOpenFilesCacheCapacity() int {
	switch runtime.GOOS {
	case "darwin":
		return 20
	case "windows":
		return 200
	default:
		return 200
	}
}

type CacheManager interface {
	DB() db.DB

	Add(types.HashHeight, db.Patch) error
	Pop() error

	// Stop releases the LevelDB handle. It is idempotent: the first call
	// closes the handle and reports any error from doing so, every later call
	// is a no-op that returns nil. After Stop, DB returns nil and Add and Pop
	// return leveldb.ErrClosed.
	Stop() error
}

// ErrCacheIdentityMismatch preserves the existing startup error text. It is
// returned before any rollback write when the retained hash is not the target.
var ErrCacheIdentityMismatch = errors.New("The cache's state is incorrect. You can fix the problem by removing the cache database manually.")

// IdentifierRollbackManager is an optional capability, separate from the legacy
// CacheManager interface. Implementations validate the full retained identifier
// before changing cache data; height equality alone is insufficient.
type IdentifierRollbackManager interface {
	RollbackTo(types.HashHeight) error
}

type cacheManager struct {
	ldb     *leveldb.DB
	write   func(*leveldb.Batch) error
	changes sync.Mutex
	stopped bool
}

func NewCacheDBManager(dataDir string) CacheManager {
	opts := &opt.Options{OpenFilesCacheCapacity: getConsensusOpenFilesCacheCapacity()}
	db, err := leveldb.OpenFile(path.Join(dataDir, "cache"), opts)
	common.DealWithErr(err)
	return &cacheManager{
		ldb: db,
		write: func(batch *leveldb.Batch) error {
			return db.Write(batch, nil)
		},
	}
}

func GetRollbackCacheSize() int {
	return rollbackCacheSize
}

func GetFrontierIdentifier(db db.DB) types.HashHeight {
	data, err := db.Get(frontierIdentifierKey)
	if err == leveldb.ErrNotFound {
		return types.ZeroHashHeight
	}
	common.DealWithErr(err)
	hh, err := types.DeserializeHashHeight(data)
	common.DealWithErr(err)
	return *hh
}

func (m *cacheManager) DB() db.DB {
	m.changes.Lock()
	defer m.changes.Unlock()
	if m.stopped {
		return nil
	}
	return db.NewLevelDBWrapper(m.ldb).Subset(storageByte)
}

func (m *cacheManager) Add(identifier types.HashHeight, patch db.Patch) error {
	temp := db.NewMemDB()
	if err := temp.Put(frontierIdentifierKey, identifier.Serialize()); err != nil {
		return err
	}
	frontierPatch, err := temp.Changes()
	if err != nil {
		return err
	}
	if err := frontierPatch.Replay(patch); err != nil {
		return err
	}
	m.changes.Lock()
	defer m.changes.Unlock()
	if m.stopped {
		return leveldb.ErrClosed
	}

	rollbackPatch := db.RollbackPatch(db.NewLevelDBWrapperWithFullDelete(m.ldb).Subset(storageByte), patch)
	batch := new(leveldb.Batch)
	batch.Put(common.JoinBytes(rollbackByte, common.Uint64ToBytes(identifier.Height)), rollbackPatch.Dump())
	if identifier.Height > rollbackCacheSize {
		batch.Delete(common.JoinBytes(rollbackByte, common.Uint64ToBytes(identifier.Height-rollbackCacheSize)))
	}
	if err := db.AppendPatchToLevelDBBatch(batch, storageByte, patch, true); err != nil {
		return err
	}
	if err := m.write(batch); err != nil {
		return err
	}
	// Compact the db manually since the automatic compaction mechanism causes performance issues when throughput increases.
	if identifier.Height%100 == 0 {
		m.ldb.CompactRange(*util.BytesPrefix([]byte{}))
	}
	return nil
}

func (m *cacheManager) Pop() error {
	m.changes.Lock()
	defer m.changes.Unlock()
	if m.stopped {
		return leveldb.ErrClosed
	}

	frontierIdentifier := GetFrontierIdentifier(db.NewLevelDBWrapper(m.ldb).Subset(storageByte))
	rollbackPatch, err := m.getRollback(frontierIdentifier.Height)
	if err != nil {
		return err
	}

	batch := new(leveldb.Batch)
	if err := db.AppendPatchToLevelDBBatch(batch, storageByte, rollbackPatch, true); err != nil {
		return err
	}
	batch.Delete(common.JoinBytes(rollbackByte, common.Uint64ToBytes(frontierIdentifier.Height)))
	return m.write(batch)
}

func (m *cacheManager) Stop() error {
	m.changes.Lock()
	defer m.changes.Unlock()
	// A second Stop is a no-op: the handle is already closed and nil.
	if m.stopped {
		return nil
	}
	// goleveldb marks the handle closed before it does any work and answers
	// every later call with ErrClosed, so the manager is stopped whatever
	// Close returns; only the error is reported.
	err := m.ldb.Close()
	m.stopped = true
	m.ldb = nil
	return err
}

func (m *cacheManager) getRollback(height uint64) (db.Patch, error) {
	snapshot, err := m.ldb.GetSnapshot()
	if err != nil {
		return nil, err
	}
	defer snapshot.Release()

	value, err := snapshot.Get(common.JoinBytes(rollbackByte, common.Uint64ToBytes(height)), nil)
	if err != nil {
		return nil, err
	}

	patch, err := db.NewPatchFromDump(value)
	if err != nil {
		return nil, err
	}
	return patch, nil
}

// rollbackFrontier projects only the logical frontier from a reverse patch.
// Patch Replay retains operation order; other cache keys need no second copy.
type rollbackFrontier struct {
	found bool
	id    types.HashHeight
	err   error
}

func (r *rollbackFrontier) Put(key, value []byte) {
	if !bytes.Equal(key, frontierIdentifierKey) || r.err != nil {
		return
	}
	r.found = true
	id, err := types.DeserializeHashHeight(value)
	if err != nil {
		r.err = err
		return
	}
	r.id = *id
}

func (r *rollbackFrontier) Delete(key []byte) {
	if !bytes.Equal(key, frontierIdentifierKey) || r.err != nil {
		return
	}
	r.found = true
	r.id = types.ZeroHashHeight
}

func cacheSnapshotFrontier(snapshot *leveldb.Snapshot) (types.HashHeight, error) {
	raw, err := snapshot.Get(common.JoinBytes(storageByte, frontierIdentifierKey), nil)
	if err == leveldb.ErrNotFound {
		return types.ZeroHashHeight, nil
	}
	if err != nil {
		return types.ZeroHashHeight, err
	}
	// The native cache wrapper uses a zero presence byte before protobuf.
	if len(raw) < 2 || raw[0] != 0 {
		return types.ZeroHashHeight, errors.New("invalid cache frontier encoding")
	}
	id, err := types.DeserializeHashHeight(raw[1:])
	if err != nil {
		return types.ZeroHashHeight, err
	}
	return *id, nil
}

func cacheSnapshotRollback(snapshot *leveldb.Snapshot, height uint64) (db.Patch, error) {
	raw, err := snapshot.Get(common.JoinBytes(rollbackByte, common.Uint64ToBytes(height)), nil)
	if err != nil {
		return nil, err
	}
	return db.NewPatchFromDump(raw)
}

// RollbackTo preflights at most rollbackCacheSize reverse patches under the
// native manager's writer lock and one snapshot. A wrong hash, malformed path
// or unavailable patch therefore refuses before any write. It keeps one patch
// at a time rather than copying the complete cache or aggregating the window.
//
// Applying an already validated path still uses separate native write batches.
// A write failure can leave acknowledged earlier steps committed. The returned
// error is not an all-window atomicity or power-loss durability guarantee, and
// callers must treat an I/O failure as an uncertain recovery outcome.
func (m *cacheManager) RollbackTo(target types.HashHeight) error {
	m.changes.Lock()
	defer m.changes.Unlock()
	if m.stopped {
		return leveldb.ErrClosed
	}
	snapshot, err := m.ldb.GetSnapshot()
	if err != nil {
		return err
	}
	defer snapshot.Release()
	current, err := cacheSnapshotFrontier(snapshot)
	if err != nil {
		return err
	}
	if target.Height > current.Height || current.Height-target.Height > uint64(rollbackCacheSize) {
		return errors.New("cache rollback target is outside the retained window")
	}
	retained := current
	for retained.Height > target.Height {
		patch, err := cacheSnapshotRollback(snapshot, retained.Height)
		if err != nil {
			return err
		}
		projection := new(rollbackFrontier)
		if err := patch.Replay(projection); err != nil {
			return err
		}
		if projection.err != nil {
			return projection.err
		}
		if !projection.found || projection.id.Height != retained.Height-1 {
			return errors.New("invalid cache rollback frontier transition")
		}
		retained = projection.id
	}
	if retained != target {
		return ErrCacheIdentityMismatch
	}
	for height := current.Height; height > target.Height; height-- {
		patch, err := cacheSnapshotRollback(snapshot, height)
		if err != nil {
			return fmt.Errorf("cache rollback failed after %d acknowledged steps: %w", current.Height-height, err)
		}
		batch := new(leveldb.Batch)
		if err := db.AppendPatchToLevelDBBatch(batch, storageByte, patch, true); err != nil {
			return fmt.Errorf("cache rollback failed after %d acknowledged steps: %w", current.Height-height, err)
		}
		batch.Delete(common.JoinBytes(rollbackByte, common.Uint64ToBytes(height)))
		if err := m.write(batch); err != nil {
			return fmt.Errorf("cache rollback failed after %d acknowledged steps: %w", current.Height-height, err)
		}
	}
	return nil
}

